// issue #12: the customer's discount applies once; the 5% bulk discount applies
// once, to carts with 10 or more lines.
const lines = (count, price) => Array.from({ length: count }, () => ({ price, qty: 1 }));

test('customer discount applies once to a cart under 10 lines', () => {
  // 1,000 less 10% = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

