  // 10,000 less 10% = 9,000; less 5% = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('bulk discount counts lines, not quantity', () => {
  // one line of 10 units: 1,000 less 10% = 900, no bulk discount
  assert.equal(total([{ price: 100, qty: 10 }], 0.1), 900);
});

